21. Basemap Options: Compare Styles


Multiple basemaps:

leaflet() |&gt;
  # CartoDB (light)
  addProviderTiles(
    providers$CartoDB.Positron,
    group = "CartoDB"
  ) |&gt;
  # OpenStreetMap
  addProviderTiles(
    providers$OpenStreetMap.Mapnik,
    group = "OSM"
  ) |&gt;
  # Imagery
  addProviderTiles(
    providers$Esri.WorldImagery,
    group = "Imagery"
  ) |&gt;
  # Controls
  addLayersControl(
    baseGroups = 
      c("CartoDB", "OSM", "Imagery")
  ) |&gt;
  setView(-105.27, 40.008, 10)






Try switching basemaps:

leaflet() |&gt;
  addProviderTiles(providers$CartoDB.Positron, group = "CartoDB") |&gt;
  addProviderTiles(providers$OpenStreetMap.Mapnik, group = "OSM") |&gt;
  addProviderTiles(providers$Esri.WorldImagery, group = "Imagery") |&gt;
  addLayersControl(baseGroups = c("CartoDB", "OSM", "Imagery"), position = "topleft") |&gt;
  setView(-105.27, 40.008, 10)

